        "pantalla1": "$s1.0.attributes.pantalla_pulgadas",
        "proc1": "$s1.0.attributes.procesador",
        "rating1": "$s1.0.avg_rating",
        "nombre2": "$s1.1.name",
        "id2": "$s1.1.id",
        "precio2": "$s1.1.price_clp",
        "ram2": "$s1.1.attributes.ram_gb",
        "ssd2": "$s1.1.attributes.ssd_gb",
        "pantalla2": "$s1.1.attributes.pantalla_pulgadas",
